/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// MS code
/// </summary>
[ExtensionOf(tableStr(GUPPricingRuleCopy))]
final class METGUPPricingRuleCopy_Extension
{
}

Method.Source:
/// <summary>
/// MS code
/// When init/create/copy pricing rule condition, the isOr field should also be copied.
/// In this class, insert_recordset has been overwritten because the isOR field should be considered.
/// </summary>
/// <param name = "_ruleIdCopy">RefRecId</param>    
public void initRuleConditionCopyFromPricingRule(RefRecId _ruleIdCopy)
{
    GUPPricingRuleCondition pricingRuleCondition;
    GUPPricingRuleConditionCopy pricingRuleConditionCopy;
    GUPPricingAttributeLink attributeLink;

    insert_recordset pricingRuleConditionCopy (RuleId, ConditionValue, METisOR, ConditionAttribute)
        select _ruleIdCopy, ConditionValue, METisOR from pricingRuleCondition
            where pricingRuleCondition.RuleId == this.RuleId
            join RecId from attributeLink
            order by attributeLink.Priority desc
            where attributelink.RecId == pricingRuleCondition.ConditionAttribute;
}

/// <summary>
/// MS code
/// </summary>
/// <param name = "_ruleId">RefRecId</param>
protected void createRuleConditions(RefRecId _ruleId)
{
    GUPPricingRuleCondition ruleCondition;
    GUPPricingRuleConditionCopy ruleConditionCopy;
    GUPPricingAttributeLink attributeLink;

    insert_recordset ruleCondition (RuleId, ConditionValue, METisOR, ConditionAttribute)
        select _ruleId, ConditionValue, METisOR from ruleConditionCopy
            where ruleConditionCopy.RuleId == this.RecId
            join RecId from attributeLink
            order by attributeLink.Priority desc
            where attributelink.RecId == ruleConditionCopy.ConditionAttribute;
}

/// <summary>
/// MS code
/// findExistingPricingRuleByConditionLookup need be extended, It is not covered in this example code.
/// When the feature 'Unified pricing management pricing rule performance enhancement' is enabled. All the related logic for ruleLookup table such as update lookup, insert lookup, need to be considered.
/// Also, the lookup table should consider the OR relations for each attribute. Entity should consider how to set OR relations.
/// Otherwise when we try to find if there are any existing rule for the setup(A1=V1 OR A2=V2) we might find (A1=V1 AND A2=V2) because we find the rule by condition only
/// </summary>
/// <returns>RefRecId</returns>
    protected RefRecId findExistingPricingRule()
{
    RecId ruleId = next findExistingPricingRule();       

    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        GUPPricingRule pricingRule;
        GUPPricingRuleConditionCopy ruleConditionCopy;
        select firstonly RecId from ruleConditionCopy
            where ruleConditionCopy.RuleId == this.RecId
                && ruleConditionCopy.METisOR == NoYes::yes;

        if (!ruleConditionCopy.RecId)
        {
            return ruleId;
        }

        GUPPricingRuleCondition ruleCondition;
        GUPPricingRuleExclusion pricingRuleExclusion;
        GUPPricingRuleExclusionCopy pricingRuleExclusionCopy;
        boolean hasSameExlusion;

        while select RecId from pricingRule
            where pricingRule.ExclusionType == this.ExclusionType
                && pricingRule.PriceAttributeGroupName == this.PriceAttributeGroupName
                && pricingRule.DisableMultiReference == false
            notexists join ruleCondition
                where ruleCondition.RuleId == pricingRule.RecId
                exists join ruleConditionCopy
                    where ruleConditionCopy.RuleId == this.RecId
                        && ruleConditionCopy.ConditionAttribute == ruleCondition.ConditionAttribute
                        && (ruleConditionCopy.ConditionValue != ruleCondition.ConditionValue || ruleConditionCopy.METisOR != ruleCondition.METisOR)   //check condition value and OR relation to find the correct exsting rule.
        {
            hasSameExlusion = false;
            select count(RecId) from pricingRuleExclusion where pricingRuleExclusion.RuleId == pricingRule.RecId;
            select count(RecId) from pricingRuleExclusionCopy where pricingRuleExclusionCopy.RuleId == this.RecId;

            if (pricingRuleExclusion.RecId == pricingRuleExclusionCopy.RecId)
            {
                if (pricingRuleExclusion.RecId == 0)
                {
                    hasSameExlusion = true;
                }
                else
                {
                    select firstonly RecId from pricingRuleExclusion
                        where pricingRuleExclusion.RuleId == pricingRule.RecId
                        notexists join pricingRuleExclusionCopy
                            where pricingRuleExclusionCopy.RuleId == this.RecId
                                && pricingRuleExclusionCopy.Exclusion == pricingRuleExclusion.Exclusion;

                    if (pricingRuleExclusion.RecId == 0)
                    {
                        hasSameExlusion = true;
                    }
                }

                if (hasSameExlusion)
                {
                    break;
                }
            }
        }

        return pricingRule.RecId;
    }

    return ruleId;
}
